import{c as t,Q as i,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"This paper is f*cking insane — Codex writes/Claude reviews vs Claude writes/Codex reviews","description":"","frontmatter":{"url":"https://x.com/iiiichigo_chan/status/2081784321518510439","title":"This paper is f*cking insane — Codex writes/Claude reviews vs Claude writes/Codex reviews","author":"iiiichigo_chan","archived":"2026-07-30T00:00:00.000Z","handle":"@iiiichigo_chan","published":"2026-07-27T00:00:00.000Z","stats":"37 likes · 5 retweets · 30 bookmarks · 2771 views","tags":["multi-agent","review","codex","coding-benchmark","agent-roles"],"type":"note-tweet"},"headers":[],"relativePath":"research/tweets/2026-07-27-@iiiichigo_chan-510439.md","filePath":"research/tweets/2026-07-27-@iiiichigo_chan-510439.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-27-@iiiichigo_chan-510439.md"};function o(d,e,n,h,l,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="this-paper-is-f-cking-insane-—-codex-writes-claude-reviews-vs-claude-writes-codex-reviews-—-iiiichigo-chan" tabindex="-1">This paper is f*cking insane — Codex writes/Claude reviews vs Claude writes/Codex reviews — @iiiichigo_chan <a class="header-anchor" href="#this-paper-is-f-cking-insane-—-codex-writes-claude-reviews-vs-claude-writes-codex-reviews-—-iiiichigo-chan" aria-label="Permalink to &quot;This paper is f*cking insane — Codex writes/Claude reviews vs Claude writes/Codex reviews — @iiiichigo_chan&quot;">​</a></h1><p><strong>注意</strong>：note tweet 格式，fxtwitter API 僅能取得 intro，全文請至原始連結閱讀</p><p><strong>來源</strong>：<a href="https://x.com/iiiichigo_chan/status/2081784321518510439" target="_blank" rel="noreferrer">https://x.com/iiiichigo_chan/status/2081784321518510439</a><strong>作者</strong>：iiiichigo_chan（@iiiichigo_chan） <strong>發布日期</strong>：2026-07-27 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Note Tweet <strong>統計</strong>：37 likes · 5 retweets · 30 bookmarks · 2771 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>This paper is f*cking insane.</p><p>Researchers tested two AI coding workflows that look identical:</p><p>Codex writes -&gt; Claude reviews</p><p>Claude writes -&gt; Codex reviews</p><p>Across 116 hard coding tasks:</p><p>Codex -&gt; Claude: 71.6% -&gt; 89.7%</p><p>Claude -&gt; Codex: 91.4% -&gt; 82.8%</p><p>In this test, Claude improved Codex. Codex hurt Claude.</p><p>Most people think two agents automatically means a better result.</p><p>This paper shows the roles matter more than the number of agents.</p><p>Bookmark this.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：同樣是「兩個模型互相審查」的架構，116 個高難度 coding 任務顯示 Claude 審查 Codex 大幅提升成績（71.6%→89.7%），但 Codex 審查 Claude 反而拉低成績（91.4%→82.8%）——角色分配比 agent 數量更重要。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>兩種表面相同的架構（A 寫 B 審 vs B 寫 A 審）實測結果不對稱：誰當 reviewer 決定結果好壞，不是「多一個 agent 審查」本身就會變好</li><li>反直覺結論：更強的模型當 writer、較弱模型當 reviewer 時，reviewer 可能拉低已經不錯的結果（91.4%→82.8%）</li><li>隱含推論：多 agent pipeline 設計時，writer/reviewer 角色分配需要根據模型能力差異調校，不能假設「加一層審查恆為正貢獻」</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>116 個高難度 coding 任務</li><li>Codex 寫 → Claude 審：71.6% → 89.7%（+18.1pp）</li><li>Claude 寫 → Codex 審：91.4% → 82.8%（-8.6pp）</li><li>未附論文名稱、作者、連結，無法查核原始出處</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>Note tweet 格式，僅有 intro 全文（本則實際看似完整，但無法排除截斷可能），且<strong>未附論文連結或作者名</strong>，證據可信度僅能停留在「社群轉述」層級，無法驗證方法論細節（如任務類型、模型版本、評分標準）</li><li>若數據屬實，與本 workspace <code>graph.md §G2</code>「產出者不驗收自己的產出」「verify 靠視角互斥取勝」的精神一致，但本文未說明為何角色不對稱（可能是評分模型本身能力差異，而非「角色」這個變數本身），過度簡化因果推論的風險存在</li><li>缺乏可操作細節（無 prompt、無評分 rubric、無如何避免「弱模型審查拉低結果」的具體建議），僅能作為方向性參考</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>方向性佐證既有 graph.md 產出者不自驗收原則，但無具體可套用步驟</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>角色不對稱效果的具體數字反直覺且有參考價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>引用具體論文數字但未附連結可查核來源，社群推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>3/10</td><td>無方法論細節、無 prompt，僅頭條數字</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>適用任何 writer/reviewer 雙模型 pipeline 設計場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.55/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：分數未過 6 分整合門檻，且缺乏可查核來源與可操作細節，僅存檔備查。</p>',29)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
